33	using amr_dispatcher_core::planning::PixelCoord;
34	using amr_dispatcher_core::planning::PruneConfig;
35	using amr_dispatcher_core::planning::SafetyFilterConfig;
36	using amr_dispatcher_core::planning::TopologyBuilderConfig;
37	using amr_dispatcher_core::planning::WorldCoord;
38	
39	// FNV-1a 64 位内容哈希：同地图必同 hash、异地图（尺寸/分辨率/栅格数据任一
40	// 变化）必异 hash，供调度侧版本门禁（expected_map_hash）比对。
41	std::string ComputeMapHash(const MapGrid& grid) {
42	  uint64_t h = 14695981039346656037ULL;  // FNV-1a offset basis
43	  const auto mix = [&h](const void* bytes, std::size_t n) {
44	    const auto* p = static_cast<const uint8_t*>(bytes);
45	    for (std::size_t i = 0; i < n; ++i) {
46	      h ^= p[i];
47	      h *= 1099511628211ULL;  // FNV prime
48	    }
49	  };
50	  mix(&grid.width, sizeof(grid.width));
51	  mix(&grid.height, sizeof(grid.height));
52	  mix(&grid.resolution, sizeof(grid.resolution));
53	  if (!grid.data.empty()) {
54	    mix(grid.data.data(), grid.data.size());
55	  }
56	  std::ostringstream out;
57	  out << "fnv1a64_" << std::hex << std::setfill('0') << std::setw(16) << h;
58	  return out.str();
59	}
60	
61	// 站点锚点摘要：markers 内容变化（新增/移动站点）也要触发重新生成，
62	// 否则同图重复消息会被跳过。仅摘要参与 hash，不额外读文件系统状态。
63	std::string ComputeAnchorsDigest(const std::vector<AnchorStation>& anchors) {
64	  uint64_t h = 14695981039346656037ULL;
65	  const auto mix_str = [&h](const std::string& s) {
66	    for (const char c : s) {
67	      h ^= static_cast<uint8_t>(c);
68	      h *= 1099511628211ULL;
69	    }
70	    h ^= 0xFFu;  // 分隔符，防 "ab"+"c" 与 "a"+"bc" 摘要碰撞
71	    h *= 1099511628211ULL;
72	  };
73	  const auto mix_double = [&h](double v) {
74	    uint64_t u = 0;
75	    static_assert(sizeof(u) == sizeof(v), "double must be 64-bit");
76	    std::memcpy(&u, &v, sizeof(v));
77	    for (int i = 0; i < 8; ++i) {
78	      h ^= static_cast<uint8_t>(u >> (i * 8));
79	      h *= 1099511628211ULL;
80	    }
81	  };
82	  for (const auto& a : anchors) {
83	    mix_str(a.id);
84	    mix_str(a.type);
85	    mix_double(a.x);
86	    mix_double(a.y);
87	    mix_double(a.yaw);
88	  }
89	  std::ostringstream out;
90	  out << std::hex << std::setfill('0') << std::setw(16) << h;
91	  return out.str();
92	}
93	
94	// double -> YAML 文本：max_digits10 保证往返解析不丢精度。
95	std::string FormatDouble(double v) {
96	  std::ostringstream out;
97	  out << std::setprecision(std::numeric_limits<double>::max_digits10) << v;
98	  return out.str();
99	}
100	
101	std::string Quote(const std::string& value) {
102	  return "\"" + value + "\"";
103	}
104	
105	std_msgs::msg::ColorRGBA Color(float r, float g, float b, float a = 1.0f) {
106	  std_msgs::msg::ColorRGBA c;
107	  c.r = r;
108	  c.g = g;
109	  c.b = b;
110	  c.a = a;
111	  return c;
112	}
113	
114	// 站点类型 -> RViz 颜色：pickup 绿 / dropoff 橙 / charge 黄 / 其他蓝。
115	std_msgs::msg::ColorRGBA StationColor(const std::string& type) {
116	  if (type == "pickup") {
117	    return Color(0.2f, 0.8f, 0.2f);
118	  }
119	  if (type == "dropoff") {
120	    return Color(0.95f, 0.6f, 0.1f);
121	  }
122	  if (type == "charge") {
123	    return Color(0.95f, 0.85f, 0.2f);
124	  }
125	  return Color(0.3f, 0.5f, 0.9f);
126	}
127	
128	}  // namespace
129	
130	MapIngestNode::MapIngestNode(const rclcpp::NodeOptions& options)
131	    : rclcpp::Node("map_ingest_node", options) {
132	  declare_parameter<std::string>("map_topic", "/map");
133	  declare_parameter<std::string>("markers_file", "");
134	  declare_parameter<std::string>("output_stations_file", "config/generated/stations.yaml");
135	  declare_parameter<double>("robot_radius_m", 0.25);
136	  declare_parameter<double>("safety_margin_m", 0.05);
137	  declare_parameter<double>("min_branch_length_m", 0.5);
138	  declare_parameter<double>("max_snap_dist_m", 2.0);
139	  declare_parameter<bool>("publish_markers", true);
140	  declare_parameter<std::string>("marker_topic", "/dispatcher/topology_markers");
141	
142	  map_topic_ = get_parameter("map_topic").as_string();
143	  markers_file_ = get_parameter("markers_file").as_string();
144	  output_stations_file_ = get_parameter("output_stations_file").as_string();
145	  robot_radius_m_ = get_parameter("robot_radius_m").as_double();
146	  safety_margin_m_ = get_parameter("safety_margin_m").as_double();
147	  min_branch_length_m_ = get_parameter("min_branch_length_m").as_double();
148	  max_snap_dist_m_ = get_parameter("max_snap_dist_m").as_double();
149	  publish_markers_ = get_parameter("publish_markers").as_bool();
150	  marker_topic_ = get_parameter("marker_topic").as_string();
151	
152	  // transient_local + reliable：与 nav2_map_server / 静态地图发布者的
153	  // latched 语义对接——即使 map_ingest_node 启动晚于 map_server 也能收到地图。
154	  map_sub_ = create_subscription<OccupancyGrid>(
155	      map_topic_, rclcpp::QoS(rclcpp::KeepLast(1)).transient_local().reliable(),
156	      std::bind(&MapIngestNode::MapCallback, this, std::placeholders::_1));
157	
158	  // transient_local：RViz 晚启动也能立即看到完整拓扑。
159	  marker_pub_ = create_publisher<visualization_msgs::msg::MarkerArray>(
160	      marker_topic_, rclcpp::QoS(rclcpp::KeepLast(1)).transient_local());
161	
162	  RCLCPP_INFO(get_logger(),
163	              "MapIngestNode started: map_topic=%s markers_file='%s' output='%s' "
164	              "(robot_radius=%.2fm margin=%.2fm min_branch=%.2fm max_snap=%.2fm)",
165	              map_topic_.c_str(), markers_file_.c_str(), output_stations_file_.c_str(),
166	              robot_radius_m_, safety_margin_m_, min_branch_length_m_, max_snap_dist_m_);
167	}
168	
169	std::vector<AnchorStation> MapIngestNode::LoadAnchors() const {
170	  std::vector<AnchorStation> anchors;
171	  if (markers_file_.empty()) {
172	    return anchors;
173	  }
174	  std::error_code ec;
175	  if (!std::filesystem::exists(markers_file_, ec)) {
176	    RCLCPP_WARN(get_logger(), "markers_file '%s' does not exist yet; waiting",
177	                markers_file_.c_str());
178	    return anchors;
179	  }
180	  try {
181	    const YAML::Node root = YAML::LoadFile(markers_file_);
182	    if (!root["anchors"] || !root["anchors"].IsSequence()) {
183	      RCLCPP_WARN(get_logger(), "markers_file '%s' has no 'anchors' list; waiting",
184	                  markers_file_.c_str());
185	      return anchors;
186	    }
187	    for (const auto& node : root["anchors"]) {
188	      AnchorStation anchor;
189	      anchor.id = node["id"].as<std::string>();
190	      anchor.type = node["type"].as<std::string>("normal");
191	      anchor.x = node["x"].as<double>();
192	      anchor.y = node["y"].as<double>();
193	      anchor.yaw = node["yaw"].as<double>(0.0);
194	      if (anchor.id.empty()) {
195	        RCLCPP_WARN(get_logger(), "markers_file '%s' contains an anchor with empty id; skipped",
196	                    markers_file_.c_str());
197	        continue;
198	      }
199	      anchors.push_back(std::move(anchor));
200	    }
201	  } catch (const std::exception& e) {
202	    RCLCPP_ERROR(get_logger(), "Failed to parse markers_file '%s': %s",
203	                 markers_file_.c_str(), e.what());
204	    anchors.clear();
205	  }
206	  return anchors;
207	}
208	
209	std::string MapIngestNode::SerializeCatalog(const StationCatalog& catalog) {
210	  // 与 LoadStationCatalog 的逐行严格解析 schema 对齐（Task 1）：
211	  // version(map_hash/graph_version) -> stations -> road_nodes -> edges(polyline)。
212	  std::ostringstream out;
213	  out << "version:\n";
214	  out << "  map_hash: " << Quote(catalog.map_hash) << "\n";
215	  out << "  graph_version: " << Quote(catalog.graph_version) << "\n";
216	
217	  out << "stations:\n";
218	  for (const auto& station : catalog.stations) {
219	    out << "  - id: " << Quote(station.id) << "\n";
220	    out << "    x: " << FormatDouble(station.x) << "\n";
221	    out << "    y: " << FormatDouble(station.y) << "\n";
222	    out << "    yaw: " << FormatDouble(station.yaw) << "\n";
223	    out << "    type: " << Quote(station.type) << "\n";
224	  }
225	
226	  out << "road_nodes:\n";
227	  for (const auto& node : catalog.road_nodes) {
228	    out << "  - id: " << Quote(node.id) << "\n";
229	    out << "    x: " << FormatDouble(node.x) << "\n";
230	    out << "    y: " << FormatDouble(node.y) << "\n";
231	    out << "    yaw: " << FormatDouble(node.yaw) << "\n";
232	  }
233	
234	  out << "edges:\n";
235	  for (const auto& edge : catalog.edges) {
236	    out << "  - from: " << Quote(edge.from) << "\n";
237	    out << "    to: " << Quote(edge.to) << "\n";
238	    out << "    distance_m: " << FormatDouble(edge.distance_m) << "\n";
239	    out << "    bidirectional: " << (edge.bidirectional ? "true" : "false") << "\n";
240	    out << "    enabled: " << (edge.enabled ? "true" : "false") << "\n";
241	    out << "    polyline:\n";
242	    for (const auto& point : edge.polyline) {
243	      out << "      - [" << FormatDouble(point.first) << ", " << FormatDouble(point.second)
244	          << "]\n";
245	    }
246	  }
247	  return out.str();
248	}
249	
250	bool MapIngestNode::WriteCatalogAtomic(const StationCatalog& catalog) const {
251	  const std::filesystem::path final_path(output_stations_file_);
252	  const std::filesystem::path tmp_path(final_path.string() + ".tmp");
253	  std::error_code ec;
254	
255	  if (final_path.has_parent_path()) {
256	    std::filesystem::create_directories(final_path.parent_path(), ec);
257	    if (ec) {
258	      RCLCPP_ERROR(get_logger(), "Cannot create directory for %s: %s",
259	                   final_path.parent_path().string().c_str(), ec.message().c_str());
260	      return false;
261	    }
262	  }
263	
264	  {
265	    std::ofstream out(tmp_path, std::ios::trunc);
266	    if (!out) {
267	      RCLCPP_ERROR(get_logger(), "Cannot open temp file %s for writing", tmp_path.c_str());
268	      return false;
269	    }
270	    out << SerializeCatalog(catalog);
271	    out.flush();
272	    if (!out) {
273	      out.close();
274	      std::filesystem::remove(tmp_path, ec);
275	      RCLCPP_ERROR(get_logger(), "Failed writing temp file %s", tmp_path.c_str());
276	      return false;
277	    }
278	  }
279	
280	  // 回读校验：tmp 文件必须能被调度侧的严格解析器 LoadStationCatalog 接受，
281	  // 否则删除 tmp、保留旧文件——绝不让半截/坏目录进入热重载路径。
282	  if (!LoadStationCatalog(tmp_path)) {
283	    std::filesystem::remove(tmp_path, ec);
284	    RCLCPP_ERROR(get_logger(),
285	                 "Round-trip validation failed for %s; generated YAML is not parseable "
286	                 "by LoadStationCatalog (keeping existing catalog)",
287	                 tmp_path.c_str());
288	    return false;
289	  }
290	
291	  // 同目录内 rename(2) 为原子操作：调度端要么看到旧文件要么看到新文件。
292	  std::filesystem::rename(tmp_path, final_path, ec);
293	  if (ec) {
294	    std::filesystem::remove(tmp_path, ec);
295	    RCLCPP_ERROR(get_logger(), "Atomic rename %s -> %s failed: %s", tmp_path.c_str(),
296	                 final_path.c_str(), ec.message().c_str());
297	    return false;
298	  }
299	  return true;
300	}
301	
302	void MapIngestNode::MapCallback(const OccupancyGrid::SharedPtr msg) {
303	  if (msg->info.width == 0 || msg->info.height == 0) {
304	    RCLCPP_WARN(get_logger(), "Ignoring invalid map: width=%u height=%u", msg->info.width,
305	                msg->info.height);
306	    return;
307	  }
308	  const std::size_t expected_cells =
309	      static_cast<std::size_t>(msg->info.width) * msg->info.height;
310	  if (msg->data.size() != expected_cells) {
311	    RCLCPP_WARN(get_logger(), "Ignoring malformed map: data size %zu != %u x %u",
312	                msg->data.size(), msg->info.width, msg->info.height);
313	    return;
314	  }
315	
316	  // ---- ① OccupancyGrid -> 核心库 MapGrid ----
317	  MapGrid grid;
318	  grid.width = msg->info.width;
319	  grid.height = msg->info.height;
320	  grid.resolution = msg->info.resolution;
321	  grid.origin_x = msg->info.origin.position.x;
322	  grid.origin_y = msg->info.origin.position.y;
323	  grid.origin_yaw = amr_dispatcher_core::path_tracking::YawFromQuaternion(
324	      msg->info.origin.orientation.z, msg->info.origin.orientation.w);
325	  grid.data.assign(msg->data.begin(), msg->data.end());
326	
327	  // ---- ② 加载站点锚点（markers.yaml anchors 段） ----
328	  const std::vector<AnchorStation> anchors = LoadAnchors();
329	  if (anchors.empty()) {
330	    RCLCPP_ERROR(get_logger(),
331	                 "No station anchors available (markers_file: '%s'); waiting for a valid "
332	                 "markers file before generating the catalog",
333	                 markers_file_.c_str());
334	    return;
335	  }
336	
337	  // 同图 + 同锚点重复消息：跳过重写，避免无谓触发调度侧热重载。
338	  const std::string map_hash = ComputeMapHash(grid);
339	  const std::string ingest_hash = map_hash + "#" + ComputeAnchorsDigest(anchors);
340	  if (ingest_hash == last_ingest_hash_) {
341	    RCLCPP_DEBUG(get_logger(), "Map and anchors unchanged (%s); skipping re-ingest",
342	                 map_hash.c_str());
343	    return;
344	  }
345	
346	  // ---- ③ 核心库算法流水线 ----
347	  SafetyFilterConfig safety_cfg;
348	  safety_cfg.robot_radius_m = robot_radius_m_;
349	  safety_cfg.safety_margin_m = safety_margin_m_;
350	
351	  PruneConfig prune_cfg;
352	  prune_cfg.min_branch_length_m = min_branch_length_m_;
353	  prune_cfg.resolution = grid.resolution;
354	
355	  TopologyBuilderConfig builder_cfg;
356	  builder_cfg.max_snap_dist_m = max_snap_dist_m_;
357	  builder_cfg.map_hash = map_hash;
358	  builder_cfg.graph_version = "v1";
359	
360	  const BinaryGrid safety_grid = amr_dispatcher_core::planning::FilterSafetySpace(grid, safety_cfg);
361	  const BinaryGrid skeleton = amr_dispatcher_core::planning::ZhangSuenThinning(safety_grid);
362	
363	  std::vector<PixelCoord> protected_points;
364	  protected_points.reserve(anchors.size());
365	  for (const auto& anchor : anchors) {
366	    protected_points.push_back(
367	        amr_dispatcher_core::planning::WorldToPixel(WorldCoord{anchor.x, anchor.y}, grid));
368	  }
369	  const BinaryGrid pruned =
370	      amr_dispatcher_core::planning::PruneSkeletonProtected(skeleton, protected_points, prune_cfg);
371	
372	  // ---- ④ 拓扑构建与站点吸附 ----
373	  const auto result = amr_dispatcher_core::planning::BuildTopologyCatalog(pruned, grid, anchors,
374	                                                                          builder_cfg);
375	  if (!result.success) {
376	    RCLCPP_ERROR(get_logger(), "Map ingest failed: %s (keeping existing catalog)",
377	                 result.error_message.c_str());
378	    return;
379	  }
380	
381	  // ---- ⑤ 原子写出 + RViz Marker ----
382	  if (!WriteCatalogAtomic(result.catalog)) {
383	    RCLCPP_ERROR(get_logger(), "Failed to write catalog to '%s' (keeping existing catalog)",
384	                 output_stations_file_.c_str());
385	    return;
386	  }
387	  last_ingest_hash_ = ingest_hash;
388	  if (!msg->header.frame_id.empty()) {
389	    map_frame_id_ = msg->header.frame_id;
390	  }
391	
392	  RCLCPP_INFO(get_logger(),
393	              "Successfully ingested map and generated %s (%zu stations, %zu road nodes, "
394	              "%zu edges) [map_hash=%s]",
395	              output_stations_file_.c_str(), result.catalog.stations.size(),
396	              result.catalog.road_nodes.size(), result.catalog.edges.size(), map_hash.c_str());
397	
398	  if (publish_markers_) {
399	    PublishTopologyMarkers(result.catalog);
400	  }
401	}
402	
403	void MapIngestNode::PublishTopologyMarkers(const StationCatalog& catalog) {
404	  visualization_msgs::msg::MarkerArray array;
405	  const auto stamp = now();
406	
407	  // 先 DELETEALL 清残影：重新导入（地图更新）时上一批 Marker 全部作废。
408	  visualization_msgs::msg::Marker clear;
409	  clear.header.frame_id = map_frame_id_;
410	  clear.header.stamp = stamp;
411	  clear.ns = "topology_reset";
412	  clear.id = 0;
413	  clear.action = visualization_msgs::msg::Marker::DELETEALL;
414	  array.markers.push_back(clear);
415	
416	  int id = 0;
417	  const auto base_marker = [&](const std::string& ns, int type) {
418	    visualization_msgs::msg::Marker marker;
419	    marker.header.frame_id = map_frame_id_;
420	    marker.header.stamp = stamp;
421	    marker.ns = ns;
422	    marker.id = id++;
423	    marker.type = type;
424	    marker.action = visualization_msgs::msg::Marker::ADD;
425	    marker.pose.orientation.w = 1.0;
426	    // 永久驻留（lifetime=0）+ transient_local 发布：晚加入的 RViz 也能看到。
427	    return marker;
428	  };
429	
430	  // 端点查找表：折线退化（<2 点）时回退用站点/节点坐标补两个端点。
431	  std::unordered_map<std::string, std::pair<double, double>> endpoint_xy;
432	  for (const auto& node : catalog.road_nodes) {
433	    endpoint_xy[node.id] = {node.x, node.y};
434	    auto marker = base_marker("road_nodes", visualization_msgs::msg::Marker::SPHERE);
435	    marker.pose.position.x = node.x;
436	    marker.pose.position.y = node.y;
437	    marker.pose.position.z = 0.05;
438	    marker.scale.x = 0.15;
439	    marker.scale.y = 0.15;
440	    marker.scale.z = 0.15;
441	    marker.color = Color(0.65f, 0.65f, 0.65f, 0.9f);
442	    array.markers.push_back(marker);
443	  }
444	
445	  for (const auto& station : catalog.stations) {
446	    endpoint_xy[station.id] = {station.x, station.y};
447	    auto marker = base_marker("stations", visualization_msgs::msg::Marker::CYLINDER);
448	    marker.pose.position.x = station.x;
449	    marker.pose.position.y = station.y;
450	    marker.pose.position.z = 0.05;
451	    marker.scale.x = 0.3;
452	    marker.scale.y = 0.3;
453	    marker.scale.z = 0.1;
454	    marker.color = StationColor(station.type);
455	    array.markers.push_back(marker);
456	
457	    auto label = base_marker("station_labels", visualization_msgs::msg::Marker::TEXT_VIEW_FACING);
458	    label.pose.position.x = station.x;
459	    label.pose.position.y = station.y;
460	    label.pose.position.z = 0.5;
461	    label.scale.z = 0.25;
462	    label.color = Color(1.0f, 1.0f, 1.0f, 0.95f);
463	    label.text = station.id;
464	    array.markers.push_back(label);
465	  }
466	
467	  // 边：LINE_STRIP 沿真实 polyline 走廊中心线（而非两点直线）。
468	  for (const auto& edge : catalog.edges) {
469	    auto marker = base_marker("edges", visualization_msgs::msg::Marker::LINE_STRIP);
470	    marker.scale.x = 0.06;  // 线宽（米）
471	    marker.color = Color(0.1f, 0.8f, 0.9f, 0.9f);
472	    if (edge.polyline.size() >= 2) {
473	      marker.points.reserve(edge.polyline.size());
474	      for (const auto& point : edge.polyline) {
475	        geometry_msgs::msg::Point p;
476	        p.x = point.first;
477	        p.y = point.second;
478	        p.z = 0.03;
479	        marker.points.push_back(p);
480	      }
481	    } else {
482	      // 折线缺失的退化边：以两端点连线兜底，保证拓扑关系仍可视化。
483	      const auto from = endpoint_xy.find(edge.from);
484	      const auto to = endpoint_xy.find(edge.to);
485	      if (from == endpoint_xy.end() || to == endpoint_xy.end()) {
486	        continue;
487	      }
488	      geometry_msgs::msg::Point a;
489	      a.x = from->second.first;
490	      a.y = from->second.second;
491	      a.z = 0.03;
492	      geometry_msgs::msg::Point b;
493	      b.x = to->second.first;
494	      b.y = to->second.second;
495	      b.z = 0.03;
496	      marker.points.push_back(a);
497	      marker.points.push_back(b);
498	    }
499	    array.markers.push_back(marker);
500	  }
501	
502	  marker_pub_->publish(array);
503	  RCLCPP_INFO(get_logger(), "Published topology markers: %zu stations, %zu road nodes, "
504	              "%zu edges on %s",
505	              catalog.stations.size(), catalog.road_nodes.size(), catalog.edges.size(),
506	              marker_topic_.c_str());
507	}
508	
509	}  // namespace amr_dispatcher_ros
510	
511	int main(int argc, char** argv) {
512	  rclcpp::init(argc, argv);
513	  rclcpp::spin(std::make_shared<amr_dispatcher_ros::MapIngestNode>());
514	  rclcpp::shutdown();
515	  return 0;
516	}
