          has_topology_ = true;
          PublishMarkers();
        });

    timer_ = create_wall_timer(500ms, [this]() { PublishMarkers(); });
    RCLCPP_INFO(get_logger(), "Dispatcher Visualizer started on topic: %s", marker_topic_.c_str());
  }

 private:
