  }
  EXPECT_TRUE(reloader.Tick());  // 晚出现 → 补加载成功并计一次换新
  EXPECT_TRUE(reloader.loaded());
  EXPECT_EQ(reloader.catalog().stations.size(), 2u);
  EXPECT_TRUE(reloader.last_error().empty());

